package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.ServiceCertificateIdentity;
import com.ruoyi.medical.workflow.DocumentCheckProtocol;
import jakarta.servlet.http.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
/** Dedicated N07 service routes. No human session, candidate or successful TASK is reopened. */
@RestController
@ConditionalOnProperty(name="medical.professional-runtime.document-review-enabled",havingValue="true",matchIfMissing=false)
public final class DocumentReviewRuntimeController {
 private final JdbcTemplate db;private final DocumentReviewControlAccess controls;private final DocumentReviewLaunchLedger launches;private final DocumentReviewRuntimeObservations observations;private final DocumentReviewHostBootstrap bootstrap;private final DocumentReviewHostOrchestrator host;private final DocumentReviewFinishOrchestrator finish;private final DocumentReviewCompletionLedger completions;private final DocumentReviewResultService results;private final DocumentReviewSupervisorGate gate;private final DocumentReviewInvocationBridge models;private final ServiceCertificateIdentity services;private final TaskSourceVerifierSchema schema=new TaskSourceVerifierSchema();
 public DocumentReviewRuntimeController(@org.springframework.beans.factory.annotation.Qualifier("masterDataSource")DataSource data,DocumentReviewControlAccess controls,DocumentReviewLaunchLedger launches,DocumentReviewRuntimeObservations observations,DocumentReviewHostBootstrap bootstrap,DocumentReviewHostOrchestrator host,DocumentReviewFinishOrchestrator finish,DocumentReviewCompletionLedger completions,DocumentReviewResultService results,DocumentReviewSupervisorGate gate,DocumentReviewInvocationBridge models,@org.springframework.beans.factory.annotation.Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity services){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.controls=controls;this.launches=launches;this.observations=observations;this.bootstrap=bootstrap;this.host=host;this.finish=finish;this.completions=completions;this.results=results;this.gate=gate;this.models=models;this.services=services;}
 @PostMapping("/internal/v1/document-review-runtime/open-workflow") public JsonNode open(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"reference");var ref=new JsonMapper().treeToValue(b.required("reference"),DocumentCheckProtocol.Reference.class);return bootstrap.open(q,ref,host::prepare);}
 @PostMapping("/internal/v1/document-review-runtime/completed-original") public JsonNode original(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"reference");var ref=new JsonMapper().treeToValue(b.required("reference"),DocumentCheckProtocol.Reference.class);return complete(q,ref.tenantId(),ref.runId(),ref);}
 @PostMapping("/internal/v1/document-review-runtime/admit") public JsonNode admit(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id");return bootstrap.existing(q,b.required("binding"),h->{session(h,b);var start=host.admit(q,h);return reply(b,"CURRENT").put("isolation_receipt_id",text(start,"isolation_receipt_id")).put("supervision_sha256",text(start,"supervision_sha256"));});}
 @PostMapping("/internal/v1/document-review-runtime/heartbeat") public JsonNode heartbeat(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id");return bootstrap.existing(q,b.required("binding"),h->{session(h,b);h.execute(s->{if(!"OPEN".equals(s.state()))deny();return null;});h.heartbeat();return reply(b,"CURRENT");});}
 @PostMapping("/internal/v1/document-review-runtime/bridge") public JsonNode bridge(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id","method","route","body","idempotency_key","model_request_observation");return bootstrap.existing(q,b.required("binding"),h->{session(h,b);return models.forward(q,h,text(b,"session_id"),text(b,"method"),text(b,"route"),nullable(b.required("body")),b.required("idempotency_key").isNull()?null:text(b,"idempotency_key"),nullable(b.required("model_request_observation")));});}
 @PostMapping("/internal/v1/document-review-runtime/finish") public JsonNode finish(HttpServletRequest q,HttpServletResponse r)throws Exception{var b=body(q,r);closed(b,"binding","session_id","observation","files");bootstrap.existing(q,b.required("binding"),h->{session(h,b);finish.save(q,h);return null;});return complete(q,text(b.required("binding"),"tenant_id"),text(b.required("binding"),"run_id"),null);}
 @PostMapping("/internal/v1/document-review-runtime/close-admission") public JsonNode close(HttpServletRequest q,HttpServletResponse r)throws Exception{return observations.close(q,body(q,r));}
 @PostMapping("/internal/v1/document-review-runtime/failure") public JsonNode failure(HttpServletRequest q,HttpServletResponse r)throws Exception{return observations.failure(q,body(q,r));}
 @PostMapping("/internal/v1/document-review-runtime/status") public JsonNode status(HttpServletRequest q,HttpServletResponse r)throws Exception{return observations.status(q,body(q,r));}
 @PostMapping("/internal/v1/document-review-runtime/supervisor-plan") public JsonNode plan(HttpServletRequest q,HttpServletResponse r)throws Exception{return gate.read(q,body(q,r),false);}
 @PostMapping("/internal/v1/document-review-runtime/supervisor-admission") public JsonNode gate(HttpServletRequest q,HttpServletResponse r)throws Exception{return gate.read(q,body(q,r),true);}
 private JsonNode complete(HttpServletRequest http,String tenant,String run,DocumentCheckProtocol.Reference expected)throws Exception{
  WireValues.uuid(tenant);WireValues.uuid(run);var commands=db.query("SELECT operation_id FROM document_review_execution WHERE tenant_id=? AND run_id=? LIMIT 2",(r,n)->r.getString(1),tenant,run);if(commands.size()!=1)deny();return controls.withReads(http,tenant,run,commands.get(0),reads->reads.execute(a->ThrowingSupplier.of(()->{
   var original=launches.recoveryOriginal(tenant,run);if(expected!=null&&!expected.equals(original.reference()))deny();launches.requireAccepted(original.reference());var result=results.readOriginal(a,reads.job());if(result==null)throw new MissingOriginalResult();return new JsonMapper().<JsonNode>valueToTree(completions.finish(a,reads.job(),result));
  }).get()));
 }
 private void session(DocumentReviewHostAccess.Handle h,JsonNode b)throws Exception{String id=text(b,"session_id");WireValues.uuid(id);h.prepare(e->{if(!id.equals(e.sessionId()))deny();return null;});}
 private JsonNode body(HttpServletRequest q,HttpServletResponse r)throws Exception{r.setHeader("Cache-Control","no-store");services.require(q);if(q.getQueryString()!=null||q.getHeader("Origin")!=null||q.getHeader("Sec-Fetch-Site")!=null)deny();int max=16777216;if(q.getContentLengthLong()>max)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] bytes=q.getInputStream().readNBytes(max+1);if(bytes.length==0||bytes.length>max)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return schema.read(bytes);}
 private static com.fasterxml.jackson.databind.node.ObjectNode reply(JsonNode b,String state){var out=new JsonMapper().createObjectNode().put("session_id",text(b,"session_id")).put("admission",state);out.set("binding",b.required("binding").deepCopy());return out;}
 private static void closed(JsonNode n,String...fields){ProfessionalRuntimeObservations.closed(n,Set.of(fields));}private static JsonNode nullable(JsonNode n){return n.isNull()?null:n;}private static String text(JsonNode n,String field){if(!n.required(field).isTextual())deny();return n.required(field).textValue();}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
 private static final class MissingOriginalResult extends RuntimeException{}
 @ExceptionHandler(MissingOriginalResult.class)public void missing(HttpServletResponse response)throws java.io.IOException{response.setHeader("Cache-Control","no-store");new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,404,ErrorCode.DEPENDENCY_UNAVAILABLE);}
 @ExceptionHandler({TenantAccessException.class,SecurityException.class})public void denied(Exception error,HttpServletResponse response)throws java.io.IOException{var code=error instanceof TenantAccessException e?e.code():ErrorCode.ACCESS_DENIED;response.setHeader("Cache-Control","no-store");new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(response,code==ErrorCode.ACCESS_DENIED?403:code==ErrorCode.DEPENDENCY_UNAVAILABLE?503:422,code);}
}
